1|// Gutenberg ingest: strip the license wrapper, drop front matter, split
2|// chapters into paragraphs with global ordinals.
3|import { paragraphId } from "./ids";
4|import type { Book, Chapter, Paragraph } from "./types";
5|
6|const START_MARKER = "*** START OF THE PROJECT GUTENBERG EBOOK";
7|const END_MARKER = "*** END OF THE PROJECT GUTENBERG EBOOK";
8|
9|// Matches a real chapter heading line ("Chapter I") after trimming, so the
10|// indented Contents lines (" Chapter I. The Cyclone") never match.
11|export const CHAPTER_HEADING = /^Chapter ([IVXLC]+)$/;
12|
13|export function stripGutenberg(raw: string): string {
14|  const start = raw.indexOf(START_MARKER);
15|  const end = raw.indexOf(END_MARKER);
16|  if (start === -1 || end === -1 || end <= start) {
17|    throw new Error("Gutenberg START/END markers missing or out of order");
18|  }
19|  const startLine = raw.indexOf("\n", start);
20|  const endLine = raw.lastIndexOf("\n", end);
21|  return raw.slice(startLine + 1, endLine);
22|}
23|
24|export function splitParagraphs(text: string): string[] {
25|  return text
26|    .replace(/\r\n?/g, "\n")
27|    .split(/\n[ \t]*\n/)
28|    .map((block) => block.replace(/[ \t]*\n[ \t]*/g, " ").replace(/\s+/g, " ").trim())
29|    .filter((block) => block.length > 0);
30|}
31|
32|interface ChapterDraft {
33|  title: string;
34|  paragraphs: string[];
35|}
36|
37|// Splits stripped body text into chapters. Works line by line because
38|// the heading and its title sit on adjacent lines with no blank line
39|// between them. Drops everything before the first chapter heading
40|// (title page, Contents, Introduction) and any [Illustration...] line.
41|export function splitChapters(body: string): ChapterDraft[] {
42|  const chapters: ChapterDraft[] = [];
43|  let current: ChapterDraft | null = null;
44|  let titlePending = false;
45|  let buffer: string[] = [];
46|  const flush = (): string => {
47|    const para = buffer.join(" ").replace(/\s+/g, " ").trim();
48|    buffer = [];
49|    return para;
50|  };
51|  const pushPara = (para: string): void => {
52|    if (para.length === 0 || /^\[Illustration/.test(para)) return;
53|    if (current === null) return; // front matter before chapter one
54|    if (titlePending) {
55|      current.title = para;
56|      titlePending = false;
57|      return;
58|    }
59|    current.paragraphs.push(para);
60|  };
61|  for (const line of body.replace(/\r\n?/g, "\n").split("\n")) {
62|    const trimmed = line.trim();
63|    if (trimmed.length === 0) {
64|      pushPara(flush());
65|      continue;
66|    }
67|    if (CHAPTER_HEADING.exec(trimmed)) {
68|      pushPara(flush());
69|      current = { title: "", paragraphs: [] };
70|      chapters.push(current);
71|      titlePending = true;
72|      continue;
73|    }
74|    buffer.push(trimmed);
75|  }
76|  pushPara(flush());
77|  return chapters.filter((chapter) => chapter.paragraphs.length > 0);
78|}
79|
80|export function buildBook(input: {
81|  id: string;
82|  title: string;
83|  author: string;
84|  gutenberg: number;
85|  chapters: { title: string; paragraphs: string[] }[];
86|}): Omit<Book, "textVersion"> {
87|  const chapters: Chapter[] = [];
88|  const paragraphs: Paragraph[] = [];
89|  let n = 0;
90|  input.chapters.forEach((draft, index) => {
91|    const ch = index + 1;
92|    const start_n = n + 1;
93|    draft.paragraphs.forEach((text, k) => {
94|      n += 1;
95|      paragraphs.push({ id: paragraphId(ch, k + 1), ch, n, text });
96|    });
97|    chapters.push({ ch, title: draft.title, start_n, end_n: n });
98|  });
99|  return {
100|    id: input.id,
101|    title: input.title,
102|    author: input.author,
103|    source: {
104|      gutenberg: input.gutenberg,
105|      url: `https://www.gutenberg.org/ebooks/${input.gutenberg}`,
106|    },
107|    chapters,
108|    paragraphs,
109|  };
110|}
111|
112|// Canonical hash input: one `id\ttext` line per paragraph.
113|export function canonicalLines(paragraphs: Pick<Paragraph, "id" | "text">[]): string {
114|  return paragraphs.map((p) => `${p.id}\t${p.text}`).join("\n");
115|}

Read text file `pipeline/ingest.ts`.
1|// Step 1: ingest the raw Gutenberg text into data/books/<key>/book.json.
2|// Frozen: a textVersion drift fails unless --force; a match leaves the
3|// file untouched.
4|import { createHash } from "node:crypto";
5|import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
6|import { join } from "node:path";
7|import { buildBook, canonicalLines, splitChapters, stripGutenberg } from "../core/gutenberg";
8|import type { Book } from "../core/types";
9|import books from "./books.json" with { type: "json" };
10|
11|export interface StepCtx {
12|  bookKey: string;
13|  force: boolean;
14|  dir: string;
15|}
16|
17|export function bookConfig(bookKey: string): { gutenberg: number; title: string; author: string } {
18|  const config = (books as Record<string, { gutenberg: number; title: string; author: string }>)[bookKey];
19|  if (!config) throw new Error(`unknown book "${bookKey}", valid keys: ${Object.keys(books).join(", ")}`);
20|  return config;
21|}
22|
23|export function textVersionFor(book: Omit<Book, "textVersion">): string {
24|  return `sha256:${createHash("sha256").update(canonicalLines(book.paragraphs)).digest("hex")}`;
25|}
26|
27|async function loadRaw(bookKey: string, gutenberg: number, fetchFn: typeof fetch): Promise<string> {
28|  const local = join("data", "raw", bookKey, `pg${gutenberg}.txt`);
29|  if (existsSync(local)) return readFileSync(local, "utf8");
30|  const url = `https://www.gutenberg.org/cache/epub/${gutenberg}/pg${gutenberg}.txt`;
31|  const response = await fetchFn(url);
32|  if (!response.ok) throw new Error(`download failed with status ${response.status}`);
33|  return await response.text();
34|}
35|
36|export async function runIngest(ctx: StepCtx, deps?: { fetchFn?: typeof fetch }): Promise<Book> {
37|  const config = bookConfig(ctx.bookKey);
38|  const raw = await loadRaw(ctx.bookKey, config.gutenberg, deps?.fetchFn ?? fetch);
39|  const drafts = splitChapters(stripGutenberg(raw));
40|  if (drafts.length === 0) throw new Error("no chapters found after ingest");
41|  const book = { ...buildBook({ id: ctx.bookKey, ...config, chapters: drafts }), textVersion: "" };
42|  book.textVersion = textVersionFor(book);
43|  mkdirSync(ctx.dir, { recursive: true });
44|  const path = join(ctx.dir, "book.json");
45|  if (existsSync(path)) {
46|    const existing = JSON.parse(readFileSync(path, "utf8")) as Book;
47|    if (existing.textVersion === book.textVersion) return existing;
48|    if (!ctx.force) {
49|      throw new Error(`textVersion drift for ${ctx.bookKey} (rerun with --force to overwrite)`);
50|    }
51|  }
52|  writeFileSync(path, `${JSON.stringify(book)}\n`);
53|  return book;
54|}

