1|// Model price table (USD per 1M tokens) and cost helpers. Cached Meta
2|// tokens are part of prompt_tokens and bill at the cached rate.
3|export const PRICES = {
4|  jevInputPer1M: 0.042,
5|  metaInputPer1M: 0.1,
6|  metaCachedPer1M: 0.002,
7|  metaOutputPer1M: 0.2,
8|} as const;
9|
10|export function jevCostUsd(inputTokens: number): number {
11|  return (inputTokens / 1_000_000) * PRICES.jevInputPer1M;
12|}
13|
14|export function metaCostUsd(input: { prompt: number; cached: number; completion: number }): number {
15|  const fresh = Math.max(0, input.prompt - input.cached);
16|  return (
17|    (fresh / 1_000_000) * PRICES.metaInputPer1M +
18|    (input.cached / 1_000_000) * PRICES.metaCachedPer1M +
19|    (input.completion / 1_000_000) * PRICES.metaOutputPer1M
20|  );
21|}

