  "asombro",
] as const;

export type EmotionId = (typeof EMOTIONS)[number];
export type JevEmotionId = EmotionId | "unknown";

export interface Book {
  id: string;
  title: string;
  author: string;
  source: { gutenberg: number; url: string };
  textVersion: string;
  chapters: Chapter[];
  paragraphs: Paragraph[];
}

